        dx = m === left ? -1 : m === right ? 1 : 0;
        dz = m === top ? -1 : m === bottom ? 1 : 0;
        dist = 0;
      } else {
        dx /= dist;
        dz /= dist;
      }
      const push = r - dist;
      this.x += dx * push;
      this.z += dz * push;
      const vn = this.vx * dx + this.vz * dz;
      if (vn < 0) {
        this.vx -= (1 + CAR.restitution) * vn * dx;
        this.vz -= (1 + CAR.restitution) * vn * dz;
